# ── Logging ────────────────────────────────────────────────────

def _log(msg: str) -> None:
    ts = time.strftime("%Y-%m-%dT%H:%M:%S")
    line = f"[{ts}] {msg}\n"
    try:
        LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        with open(LOG_PATH, "a") as f:
            f.write(line)
    except OSError:
        pass
    sys.stderr.write(line)


# ── HTTP helpers ───────────────────────────────────────────────

def _http_request(
    method: str,
    url: str,
    payload: dict | None = None,
    headers: dict | None = None,
    timeout: int = 15,
) -> dict:
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    req_headers = {"Content-Type": "application/json"}
    if headers:
        req_headers.update(headers)
    req = urllib.request.Request(url, data=data, headers=req_headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8")
            return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        # Attach the server body so the main loop can log it before
        # backoff — invaluable for debugging 400s that would otherwise
        # just say "Bad Request".
        try:
            body = e.read().decode("utf-8")
            e.server_body = body  # type: ignore[attr-defined]
        except Exception:
            e.server_body = ""  # type: ignore[attr-defined]
        raise


# ── Config + auth ──────────────────────────────────────────────

def load_config() -> dict:
    if not CONFIG_PATH.is_file():
        raise RuntimeError(
            f"Config {CONFIG_PATH} missing. Run tnode-setup.sh register step."
        )
    with open(CONFIG_PATH) as f:
        cfg = json.load(f)
    for k in ("nodeId", "nodeSecret", "mintUrl"):
        if not cfg.get(k):
            raise RuntimeError(f"Config missing {k}")
    return cfg


def _read_current_secret() -> str | None:
    """Re-read tnode-chat-sync.json from disk to pick up self-heal rotations
    by chat-sync (v1.8.15+ regenerates nodeSecret when mintNodeToken returns
    404). Without this, config-sync keeps the boot-time secret in RAM and
    loops 409 not_paired forever. Returns None on missing/invalid file."""
    try:
        with open(CONFIG_PATH) as f:
            return json.load(f).get("nodeSecret")
    except Exception:
        return None


def mint_token(cfg: dict) -> dict:
    """Mint a Firebase ID token with scope=sync_admin.

    Returns {idToken, uid, nodeId, expiresAt (epoch seconds)}.
    """
    fresh_secret = _read_current_secret()
    if fresh_secret and fresh_secret != cfg.get("nodeSecret"):
        _log("nodeSecret rotated on disk (chat-sync self-heal); reloading")
        cfg["nodeSecret"] = fresh_secret  # mutate caller's cfg in-place
    ts = str(int(time.time() * 1000))
    nonce = py_secrets.token_hex(16)
    signing = f'{cfg["nodeId"]}:{ts}:{nonce}:{SCOPE}'
    mac = hmac.new(
        cfg["nodeSecret"].encode("utf-8"),
        signing.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    mint_resp = _http_request(
        "POST",
        cfg["mintUrl"],
        {
            "nodeId": cfg["nodeId"],
            "timestamp": ts,
            "nonce": nonce,
            "signature": mac,
            "scope": SCOPE,
        },
    )
    custom_token = mint_resp["customToken"]
    api_key = cfg.get("webApiKey") or FIREBASE_WEB_API_KEY_FALLBACK
    exchange = _http_request(
        "POST",
        f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithCustomToken?key={api_key}",
        {"token": custom_token, "returnSecureToken": True},
    )
    return {
        "idToken": exchange["idToken"],
        "uid": mint_resp["uid"],
        "nodeId": mint_resp["nodeId"],
        "expiresAt": int(time.time()) + int(exchange.get("expiresIn", "3600")) - 60,
    }


# ── Firestore REST: typed value encoding ───────────────────────

def _fs_value(v):
    if v is None:
        return {"nullValue": None}
    if isinstance(v, bool):
        return {"booleanValue": v}
    if isinstance(v, int):
        return {"integerValue": str(v)}
    if isinstance(v, float):
        return {"doubleValue": v}
    if isinstance(v, str):
        return {"stringValue": v}
    if isinstance(v, dict):
        return {"mapValue": {"fields": {k: _fs_value(x) for k, x in v.items()}}}
    if isinstance(v, list):
        return {"arrayValue": {"values": [_fs_value(x) for x in v]}}
    return {"stringValue": str(v)}


def _fs_fields(d: dict) -> dict:
    return {"fields": {k: _fs_value(v) for k, v in d.items()}}


def _fs_decode(field: dict):
    """Decode a Firestore typed value back to Python."""
    if "nullValue" in field:
        return None
    if "booleanValue" in field:
        return field["booleanValue"]
    if "integerValue" in field:
        return int(field["integerValue"])
    if "doubleValue" in field:
        return float(field["doubleValue"])
    if "stringValue" in field:
        return field["stringValue"]
    if "timestampValue" in field:
        return field["timestampValue"]
    if "mapValue" in field:
        fields = field["mapValue"].get("fields", {})
        return {k: _fs_decode(v) for k, v in fields.items()}
    if "arrayValue" in field:
        values = field["arrayValue"].get("values", [])
        return [_fs_decode(v) for v in values]
    return None


def _firestore_base() -> str:
    return (
        f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
        "/databases/(default)/documents"
    )


# ── Firestore operations ───────────────────────────────────────

def query_pending_commands(token: dict) -> list[dict]:
    """Run a structured query for pending commands.

    Returns list of {id, type, params, createdAt, status} dicts.

    v1.6.0: filtra por `type IN _HANDLED_TYPES` para no agarrar commands
    de otros daemons (tnode-chat-sync maneja cron.* y tasks.*). Antes,
    config-sync se llevaba *cualquier* command pending y lo marcaba como
    `error: unknown_command_type` antes que el daemon dueño lo viera —
    rompía el flow de cualquier handler que no esté en _HANDLERS.
    """
    base = _firestore_base()
    # Parent for the collectionId `commands` nested under the node doc.
    parent = f"users/{token['uid']}/nodes/{token['nodeId']}"
    url = f"{base}/{parent}:runQuery"

    # No orderBy: a composite index (status + createdAt + type) would be
    # needed and command queues never get deep enough for ordering to
    # matter in practice. Callers that care about order can use __name__
    # which has an implicit default index.
    body = {
        "structuredQuery": {
            "from": [{"collectionId": "commands"}],
            "where": {
                "compositeFilter": {
                    "op": "AND",
                    "filters": [
                        {"fieldFilter": {
                            "field": {"fieldPath": "status"},
                            "op": "EQUAL",
                            "value": {"stringValue": "pending"},
                        }},
                        {"fieldFilter": {
                            "field": {"fieldPath": "type"},
                            "op": "IN",
                            "value": {"arrayValue": {"values": [
                                {"stringValue": t} for t in _HANDLED_TYPES
                            ]}},
                        }},
                    ],
                }
            },
            "limit": 10,
        }
    }
    headers = {"Authorization": f"Bearer {token['idToken']}"}
    resp = _http_request("POST", url, body, headers)

    # runQuery returns a list; each element may have a `document` key or be
    # an empty row (when no matches).
    cmds = []
    if isinstance(resp, list):
        rows = resp
    else:
        # Single-object response when the gateway returns only one element.
        rows = [resp]
    for row in rows:
        doc = row.get("document") if isinstance(row, dict) else None
        if not doc:
            continue
        name = doc.get("name", "")
        cmd_id = name.rsplit("/", 1)[-1]
        fields = doc.get("fields", {})
        cmds.append(
            {
                "id": cmd_id,
                "type": _fs_decode(fields.get("type", {"stringValue": ""})),
                "params": _fs_decode(fields.get("params", {"mapValue": {"fields": {}}}))
                or {},
                "createdAt": _fs_decode(fields.get("createdAt", {"nullValue": None})),
                "status": _fs_decode(fields.get("status", {"stringValue": ""})),
            }
        )
    return cmds


def update_command(token: dict, cmd_id: str, patch: dict) -> None:
    """PATCH a command doc with the given fields (status/result/completedAt)."""
    uid = token["uid"]
    node_id = token["nodeId"]
    # updateMask ensures we only touch these fields (Firestore rule also
    # enforces immutability of type/params/createdAt).
    mask_params = "&".join(
        f"updateMask.fieldPaths={urllib.parse.quote(k)}" for k in patch.keys()
    )
    url = (
        f"{_firestore_base()}/users/{uid}/nodes/{node_id}/commands/{cmd_id}"
        f"?{mask_params}"
    )
    headers = {"Authorization": f"Bearer {token['idToken']}"}
    _http_request("PATCH", url, _fs_fields(patch), headers)


# ── Fase 2/3: inventario de flota + politica de update ─────────
#
# El nodo REPORTA lo que tiene (inventory/current) y LEE lo que se quiere de el
# (policy/update). La nube nunca escribe en la cola de commands: eso preserva la
# premisa verificada en owner-kb-command-trigger-design.md §2 (cero escritores
# de nube en commands/), asi que el modelo wake-on-navegacion sigue en pie.
#
# Aqui NO se ejecuta ningun update. Fase 3 solo calcula el veredicto y lo
# publica; aplicar la politica es fase 4 y esta bloqueada por la decision de
# sudoers (ver docs/fleet-inventory-update-orchestration-design.md §6.2).

FLEET_REPORT_EVERY_S = float(
    os.environ.get("TNODE_CONFIG_SYNC_FLEET_REPORT_S", "86400")
)
_HEALTHCHECK_PATH = OPENCLAW_DIR / "scripts" / "health-check.py"


def _run_fleet_health_check() -> dict | None:
    """Corre health-check.py local y devuelve su JSON. None si no se puede.

    Se usa la copia EN el nodo, no un curl a health.tbrain.app: el reporte no
    debe depender de la red mas alla de la subida a Firestore, y el CDN de raw
    .githubusercontent sirve hasta ~4 minutos de contenido cacheado, lo que
    haria reportar un inventario medido con verifies viejos.
    """
    if not _HEALTHCHECK_PATH.is_file():
        return None
    try:
        proc = subprocess.run(
            [sys.executable, str(_HEALTHCHECK_PATH), "--no-pretty"],
            capture_output=True, text=True, timeout=180, check=False,
        )
    except Exception as e:  # noqa: BLE001
        _log(f"fleet: health-check no ejecutable: {e}")
        return None
    if not proc.stdout.strip():
        _log(f"fleet: health-check sin salida (rc={proc.returncode})")
        return None
    try:
        return json.loads(proc.stdout)
    except json.JSONDecodeError as e:
        _log(f"fleet: health-check no devolvio JSON: {e}")
        return None


def _detect_layout() -> str:
    """`tnode` si la instalacion es del usuario dedicado, `self` si es del
    usuario que corre el daemon. Determina el privilegio que necesitaria un
    update, y por eso viaja en el inventario."""
    try:
        return "tnode" if Path.home().name == "tnode" else "self"
    except Exception:  # noqa: BLE001
        return "self"


def read_update_policy(token: dict) -> dict | None:
    """Lee la politica de update del campo `updatePolicyJson` del node doc.

    Va como CAMPO del node doc, no como documento de subcoleccion, por dos
    razones concretas:

    1) Coste. El daemon ya lee campos del node doc con `_prime_node_fields`,
       una GET enmascarada que trae varios de golpe ("priming them in ONE
       masked GET turns 5+ reads into 1"). Un documento aparte no se puede
       batchear con ese prime y seria una lectura ADICIONAL por pase — que es
       justo lo que owner-kb-command-trigger-design.md §2 queria evitar al
       quitar el poll: "a escala (miles de nodos) ese poll idle = lecturas
       Firestore constantes aunque nadie haga nada".
    2) Reglas. El nodo YA puede leer su propio node doc, asi que esto no
       necesita ninguna regla nueva de Firestore. Solo la escritura del
       inventario la necesita.

    Mismo patron que `inventoryCronJson`, que ya vive asi.
    """
    try:
        raw = _firestore_get_node_field(token, "updatePolicyJson")
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise
    if not raw:
        return None
    try:
        doc = json.loads(raw) if isinstance(raw, str) else raw
    except (json.JSONDecodeError, TypeError):
        _log("fleet: updatePolicyJson no parsea como JSON")
        return None
    return doc if isinstance(doc, dict) else None


def _policy_verdict(policy: dict | None, installer_version: str) -> dict:
    """Compara el nodo contra la politica. NO ejecuta nada.

    `pending` significa que el tag deseado no coincide con el instalado, o sea
    que este nodo esta a la espera de update. Es lo que permite ver la flota
    contra un objetivo desde la consola sin haber implementado la fase 4.
    """
    if not policy:
        return {"state": "unmanaged", "reason": "sin policy/update"}
    mode = str(policy.get("mode") or "hold")
    target = str(policy.get("targetTag") or "")
    scope = str(policy.get("scope") or "safe")
    if not target:
        return {"state": "unmanaged", "reason": "policy sin targetTag",
                "mode": mode, "scope": scope}
    current_tag = f"tnode-setup-v{installer_version}" if installer_version else ""
    if current_tag and current_tag == target:
        state = "up-to-date"
    else:
        state = "pending"
    return {"state": state, "mode": mode, "scope": scope,
            "targetTag": target, "currentTag": current_tag or "unknown"}


# ── Fase 4: aplicar la politica ────────────────────────────────
#
# Tres protecciones vienen del diseno (§6.1, §6.2, §6.3) y una CUARTA no estaba
# en el: el freno de reintentos. Sin el, un targetTag que no arranca convierte la
# politica en un bucle de updates en TODA la flota a la vez. Es el fallo que mas
# dano haria de los cuatro, asi que va con contador persistente en disco.

FLEET_APPLY_ENABLED = os.environ.get("TNODE_CONFIG_SYNC_FLEET_APPLY", "1") != "0"
_FLEET_STATE_PATH = OPENCLAW_DIR / ".fleet-update-state.json"
_FLEET_MAX_ATTEMPTS = 2
_FLEET_COOLDOWN_S = 3600.0
# El tag se valida contra este patron y la URL se construye AQUI, en el nodo.
# La politica NUNCA transporta una URL: si lo hiciera, un documento de Firestore
# comprometido —o unas reglas mal puestas— serian ejecucion remota de codigo en
# toda la flota con una sola escritura.
_FLEET_TAG_RE = re.compile(r"^tnode-setup-v\d+\.\d+\.\d+$")
_FLEET_BASE_URL = "https://raw.githubusercontent.com/cmoralestbrain/tnode_server_public"


def _fleet_state_read() -> dict:
    try:
        return json.loads(_FLEET_STATE_PATH.read_text())
    except Exception:  # noqa: BLE001
        return {}


def _fleet_state_write(state: dict) -> None:
    try:
        _FLEET_STATE_PATH.write_text(json.dumps(state, indent=2))
    except Exception as e:  # noqa: BLE001
        _log(f"fleet: no se pudo guardar el estado de update: {e}")


def _fleet_can_execute() -> tuple:
    """(puede, prefijo_privilegio, motivo). Fail-safe: ante la duda, NO ejecuta.

    En layout `self` el daemon corre como dueno de la instalacion y puede correr
    el installer tal cual, sin privilegio extra.

    En layout `tnode` el daemon corre como el usuario `tnode`, que no es root.
    El installer SIN root cae silenciosamente al usuario actual y crea una
    instalacion paralela en el home equivocado (tnode-setup.sh:280), asi que
    ejecutarlo a pelo seria peor que no hacer nada. Pero el propio installer
    deja `/etc/sudoers.d/tnode` con `tnode ALL=(ALL) NOPASSWD: ALL` en cada
    provision — verificado el 2026-07-28 en los tres droplets DO y en los dos
    Oracle— asi que el privilegio YA existe.

    Se COMPRUEBA con `sudo -n true` en vez de darlo por hecho: un nodo que no lo
    tenga (sudoers recortado a mano, o una imagen distinta) se niega en vez de
    intentarlo y romper la instalacion.
    """
    if _detect_layout() == "self":
        return True, "", ""
    try:
        if os.geteuid() == 0:
            return True, "", ""
    except Exception:  # noqa: BLE001
        pass
    try:
        rc = subprocess.run(
            ["sudo", "-n", "true"], capture_output=True, timeout=10, check=False
        ).returncode
    except Exception as e:  # noqa: BLE001
        return False, "", f"no se pudo comprobar sudo: {e}"
    if rc == 0:
        return True, "sudo -n ", ""
    return False, "", "layout tnode y `sudo -n` no disponible — no se ejecuta"


def apply_update_policy(policy: dict | None, verdict: dict) -> dict:
    """Aplica la politica si toca. Devuelve el veredicto, posiblemente anotado.

    NO espera a que el update termine: el installer reinicia config-sync, asi que
    esperar significaria que el proceso muere a mitad y el resultado no se
    escribe nunca. Se lanza desprendido y la senal de fin es el SIGUIENTE reporte
    de inventario, ya del daemon reiniciado.
    """
    if not FLEET_APPLY_ENABLED:
        return verdict
    if verdict.get("state") != "pending":
        return verdict
    if str((policy or {}).get("mode") or "hold") != "auto":
        return verdict

    tag = str(verdict.get("targetTag") or "")
    if not _FLEET_TAG_RE.match(tag):
        verdict["state"] = "blocked"
        verdict["reason"] = f"targetTag con formato invalido: {tag!r}"
        _log(f"fleet: {verdict['reason']}")
        return verdict

    can, priv, why = _fleet_can_execute()
    if not can:
        verdict["state"] = "blocked"
        verdict["reason"] = why
        return verdict

    st = _fleet_state_read()
    now = time.time()
    if st.get("tag") == tag:
        attempts = int(st.get("attempts") or 0)
        last = float(st.get("lastAttemptAt") or 0)
        if attempts >= _FLEET_MAX_ATTEMPTS:
            verdict["state"] = "blocked"
            verdict["reason"] = (
                f"{attempts} intentos fallidos con {tag} — parado para no "
                "entrar en bucle; revisar a mano"
            )
            return verdict
        if (now - last) < _FLEET_COOLDOWN_S:
            verdict["state"] = "cooldown"
            verdict["reason"] = (
                f"reintento en {int(_FLEET_COOLDOWN_S - (now - last))}s"
            )
            return verdict
        st["attempts"] = attempts + 1
    else:
        st = {"tag": tag, "attempts": 1}
    st["lastAttemptAt"] = now
    _fleet_state_write(st)

    scope = str(verdict.get("scope") or "safe")
    if scope not in ("safe", "full"):
        scope = "safe"
    url = f"{_FLEET_BASE_URL}/{tag}/tnode-setup.sh"
    # curl corre SIN privilegio y solo el bash lo recibe: descargar como root
    # no aporta nada y amplia la superficie innecesariamente.
    cmd = (
        f"curl -fsSL {shlex.quote(url)} | "
        f"{priv}bash -s -- --update-only --yes --scope {shlex.quote(scope)}"
    )
    try:
        subprocess.Popen(
            ["bash", "-c", cmd],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            stdin=subprocess.DEVNULL,
            start_new_session=True,
        )
    except Exception as e:  # noqa: BLE001
        verdict["state"] = "blocked"
        verdict["reason"] = f"no se pudo lanzar el update: {e}"
        _log(f"fleet: {verdict['reason']}")
        return verdict

    verdict["state"] = "updating"
    verdict["reason"] = f"update a {tag} (scope={scope}) lanzado en background"
    _log(f"fleet: {verdict['reason']} — intento {st.get('attempts')}")
    return verdict


def write_fleet_inventory(token: dict, inventory: dict) -> None:
    """Upsert users/{uid}/nodes/{nodeId}/inventory/current."""
    uid, node_id = token["uid"], token["nodeId"]
    url = f"{_firestore_base()}/users/{uid}/nodes/{node_id}/inventory/current"
    headers = {"Authorization": f"Bearer {token['idToken']}"}
    _http_request("PATCH", url, _fs_fields(inventory), headers)


def report_fleet_inventory(token: dict) -> bool:
    """Mide, calcula el veredicto y publica. True si subio algo."""
    hc = _run_fleet_health_check()
    if hc is None:
        return False

    # La version del installer sale del components-manifest.json, que se
    # regenera en cada update. El nodo no la guardaba en ningun sitio antes de
    # v1.94.0 — sin ella no se puede comparar contra el targetTag de la
    # politica, asi que write_components_manifest la estampa ahora.
    installer_version = ""
    try:
        m = json.loads((OPENCLAW_DIR / "components-manifest.json").read_text())
        installer_version = str(m.get("installerVersion") or "")
    except Exception:  # noqa: BLE001
        pass

    policy = None
    try:
        policy = read_update_policy(token)
    except Exception as e:  # noqa: BLE001
        _log(f"fleet: no se pudo leer policy/update: {e}")

    inventory = {
        "reportedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "installerVersion": installer_version or "unknown",
        "layout": _detect_layout(),
        "summary": hc.get("summary") or {},
        "components": hc.get("components") or [],
        "policy": apply_update_policy(policy, _policy_verdict(policy, installer_version)),
    }
    write_fleet_inventory(token, inventory)
    s = inventory["summary"]
    _log(
        "fleet: inventario publicado — ok=%s warn=%s fail=%s drift=%s stale=%s policy=%s"
        % (s.get("ok"), s.get("warn"), s.get("fail"), s.get("drift"),
           s.get("manifestStale"), inventory["policy"].get("state"))
    )
    return True


def write_state(token: dict, state: dict) -> None:
    """Upsert users/{uid}/nodes/{nodeId}/state/current with the given state."""
    uid = token["uid"]
    node_id = token["nodeId"]
    url = f"{_firestore_base()}/users/{uid}/nodes/{node_id}/state/current"
    headers = {"Authorization": f"Bearer {token['idToken']}"}
    _http_request("PATCH", url, _fs_fields(state), headers)


# ── LLM mode derivation ────────────────────────────────────────

# Matches URLs whose host is localhost or a private-range IPv4 address.
# Used to detect LLM providers that run locally on the node (LM Studio,
# Ollama, llama.cpp, or any custom openai-compatible server). Provider
# name is irrelevant — users frequently use non-standard names like
# `custom-127-0-0-1-1234`.
_LOCAL_URL_RE = re.compile(
    r"^https?://(?:localhost|127\.\d+\.\d+\.\d+|0\.0\.0\.0|"
    r"192\.168\.\d+\.\d+|10\.\d+\.\d+\.\d+|"
    r"172\.(?:1[6-9]|2\d|3[01])\.\d+\.\d+)(?::\d+)?(?:/|$)"
)


def _is_local_url(url: str) -> bool:
    return bool(_LOCAL_URL_RE.match((url or "").strip().lower()))


def derive_llm_mode(openclaw_cfg: dict) -> str:
    """Return the legacy-compatible mode: 'openrouter' | 'local' | 'none'.

    ⚠️ TRANSICIÓN: la app 1.14.x compara `llmMode == "openrouter"` para
    mostrar la tarjeta de saldo, así que un nodo con key de tbrain-models
    sigue reportando ese valor (`_LEGACY_LLM_MODE`). La app nueva lee
    `modelMode` (ver derive_model_mode). Borrar en la fase de limpieza.

    - _LEGACY_LLM_MODE when the tbrain-models (or pre-rename) provider has a
      real api key — unlocks the top-up card.
    - 'local' when ANY provider has a baseUrl pointing at localhost/LAN,
      OR any other provider has both a baseUrl and an api key (Groq, Moonshot,
      custom OpenAI-compat endpoints). Node has a working LLM → banner hidden.
    - 'none' when nothing is configured → client shows the selector.
    """
    mode = derive_model_mode(openclaw_cfg)
    return _LEGACY_LLM_MODE if mode == MODELS_PROVIDER else mode


def derive_model_mode(openclaw_cfg: dict) -> str:
    """'tbrain-models' | 'local' | 'none' — mismo criterio que derive_llm_mode
    con el nombre vigente."""
    providers = (
        openclaw_cfg.get("models", {}).get("providers", {})
        if isinstance(openclaw_cfg, dict)
        else {}
    )
    if not providers:
        return "none"

    platform = (MODELS_PROVIDER, _LEGACY_TEXT_PROVIDER, MEDIA_PROVIDER)
    # apiKey puede ser string plaintext (legacy) o SecretRef dict (2.0) —
    # ambos cuentan como "key poblada" para el banner.
    if any(_apikey_present((providers.get(n) or {}).get("apiKey")) for n in platform):
        return MODELS_PROVIDER

    for name, prov in providers.items():
        if name in platform:
            continue  # already ruled out above (no usable key)
        base_url = (prov.get("baseUrl") or "").strip()
        if _is_local_url(base_url):
            return "local"
        # Remote non-platform provider with a populated key counts as
        # "functional" for banner purposes (node is ready to serve).
        if base_url and _apikey_present(prov.get("apiKey")):
            return "local"
    return "none"


def read_openclaw_json() -> dict | None:
    if not OPENCLAW_JSON_PATH.is_file():
        return None
    try:
        with open(OPENCLAW_JSON_PATH) as f:
            return json.load(f)
    except (OSError, json.JSONDecodeError) as e:
        _log(f"failed to read {OPENCLAW_JSON_PATH}: {e}")
        return None


def push_openclaw_config(token: dict) -> dict:
    """Read openclaw.json, derive llmMode, push to Firestore state/current."""
    cfg = read_openclaw_json()
    if cfg is None:
        # Still push the "none" state so the client can react.
        state = {
            "openclawConfig": None,
            "llmMode": "none",
            "updatedAt": int(time.time() * 1000),
        }
    else:
        state = {
            "openclawConfig": cfg,
            "llmMode": derive_llm_mode(cfg),
            "modelMode": derive_model_mode(cfg),
            "updatedAt": int(time.time() * 1000),
        }
    # El servidor elige el nombre del comando de key según esta capacidad
    # (functions/src/model_block.ts → applyModelKeyCommandFor).
    state["capabilities"] = [MODEL_KEY_V2_CAP]
    write_state(token, state)
    return state


# ── HTTP GET helper ────────────────────────────────────────────

def _http_get(url: str, timeout: int = 10) -> dict:
    req = urllib.request.Request(url, method="GET")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8")
        return json.loads(raw) if raw else {}


# ── OpenClaw CLI helpers ───────────────────────────────────────

def _openclaw_binary() -> str | None:
    """Locate the openclaw CLI binary on PATH or common install locations."""
    bin_path = shutil.which("openclaw")
    if bin_path:
        return bin_path
    for cand in (
        HOME / ".local" / "bin" / "openclaw",
        # Instalaciones a nivel de usuario: `npm config set prefix ~/.npm-global`.
        # Es el layout de clawpi, donde el binario vive en ~/.npm-global/bin y NO
        # aparece ni en el PATH del usuario ni en el PATH acotado de la unit
        # systemd (/usr/local/bin:/usr/bin:/bin). Sin esta ruta, _openclaw_binary
        # devolvia None y TODA invocacion del CLI fallaba con openclaw_not_found:
        # restart del gateway, apply_model_key, install_subagent, mcp.*.
        # Detectado el 2026-07-27 al estrenar verify_openclaw-cli.
        HOME / ".npm-global" / "bin" / "openclaw",
        Path("/usr/local/bin/openclaw"),
        Path("/opt/homebrew/bin/openclaw"),
    ):
        if cand.is_file() and os.access(cand, os.X_OK):
            return str(cand)
    # Ultimo recurso: preguntarle a npm por su prefijo global, para prefijos no
    # estandar. Solo se llega aqui si el binario no esta en ninguna ruta comun,
    # asi que el coste del subprocess es de camino de error.
    try:
        proc = subprocess.run(["npm", "prefix", "-g"], capture_output=True,
                              text=True, timeout=10, check=False)
        if proc.returncode == 0 and proc.stdout.strip():
            cand = Path(proc.stdout.strip()) / "bin" / "openclaw"
            if cand.is_file() and os.access(cand, os.X_OK):
                return str(cand)
    except Exception:
        pass
    return None


def _cli_env() -> dict:
    """Env for spawning the `openclaw` CLI. The CLI treats OPENCLAW_HOME as the
    PARENT of the config dir (it appends `.openclaw`), while this daemon uses
    OPENCLAW_HOME as the config dir itself. Inheriting our value makes the CLI
    resolve a doubled `.openclaw/.openclaw/` path (phantom device identities,
    stray restart-intents, failed CLI calls). Point it at the parent so the
    CLI lands on the real config dir."""
    env = os.environ.copy()
    env["OPENCLAW_HOME"] = str(OPENCLAW_DIR.parent)
    # Como servicio de sistema config-sync no hereda XDG_RUNTIME_DIR; sin él el
    # CLI del openclaw reintenta hallar el socket del gateway y se vuelve LENTO
    # (visto en `wiki ingest/compile` del handler drive_wiki_sync). Apuntarlo al
    # runtime dir del user lo hace conectar al instante.
    env.setdefault("XDG_RUNTIME_DIR", f"/run/user/{os.getuid()}")
    return env


# ── OpenClaw 2.0 Credential Management (SecretRefs + shared store) ──────────
# En el train 2.0 las API keys de model-providers NO se persisten en plaintext:
# el valor va al shared secret store (sqlite del gateway, write-only) y el
# config lleva un SecretRef {source:"store",provider:"default",id:NAME}. Eso
# saca la key de openclaw.json, de los models.json generados Y del push de
# config a Firestore (push_openclaw_config sube el config completo). El
# gateway resuelve el ref en su snapshot en memoria; rotación = store set +
# secrets reload, sin tocar config ni reiniciar. gateway.auth.token queda
# FUERA a propósito: chat-sync necesita leer ese valor y los store secrets
# son write-only por diseño (residuo documentado, evaluar en fase F3).

_SECRET_REF_SOURCES = ("env", "file", "exec", "store")


def _is_secret_ref(v) -> bool:
    return isinstance(v, dict) and v.get("source") in _SECRET_REF_SOURCES


def _secret_ref(name: str) -> dict:
    return {"source": "store", "provider": "default", "id": name}


def _secret_store_name(provider: str) -> str:
    """Nombre de entrada del store para la key de un provider, en la gramática
    del SDK (^[A-Z][A-Z0-9_]{0,127}$). tbrain-models → TBRAIN_MODELS_API_KEY."""
    base = re.sub(r"[^A-Z0-9_]", "_", provider.upper())
    if not re.match(r"^[A-Z]", base):
        base = "P_" + base
    return (base + "_API_KEY")[:128]


def _store_secret(name: str, value: str) -> bool:
    """Escribe un secret al shared store por STDIN (nunca argv/env)."""
    r = _run_openclaw(
        "secrets", "store", "set", name, "--kind", "secret",
        timeout=30, input_text=value,
    )
    if not r.get("ok"):
        _log(f"secrets: store set {name} falló: {(r.get('stderr') or r.get('error') or '')[:200]}")
    return bool(r.get("ok"))


def _secrets_reload() -> None:
    """Best-effort: re-resuelve refs al snapshot vivo del gateway. Si el
    gateway está caído no es fatal — el arranque resuelve solo."""
    r = _run_openclaw("secrets", "reload", timeout=30)
    if not r.get("ok"):
        _log(f"secrets: reload falló (no fatal): {(r.get('stderr') or r.get('error') or '')[:150]}")


def _apikey_present(v) -> bool:
    """True si el campo apiKey está poblado — plaintext real o SecretRef."""
    if _is_secret_ref(v):
        return True
    s = v.strip() if isinstance(v, str) else ""
    return bool(s) and s != "not-needed"


def _run_openclaw(
    *args: str,
    timeout: int = 60,
    stdout_limit: int = 2000,
    input_text: str | None = None,
) -> dict:
    """stdout_limit trunca al TAIL (default 2000, como siempre); 0 = sin
    truncar — necesario cuando el caller parsea JSON del stdout (un JSON
    truncado por la cabeza parece parsear y truena con 'Extra data').
    `input_text` va por stdin (para `secrets store set`: la key jamás pasa
    por argv ni env, donde `ps`/process-listing la expondrían)."""
    bin_path = _openclaw_binary()
    if not bin_path:
        return {"ok": False, "error": "openclaw_not_found"}
    try:
        proc = subprocess.run(
            [bin_path, *args],
            capture_output=True,
            text=True,
            timeout=timeout,
            check=False,
            env=_cli_env(),
            input=input_text,
        )
        result = {
            "ok": proc.returncode == 0,
            "code": proc.returncode,
            "stdout": proc.stdout[-stdout_limit:] if stdout_limit else proc.stdout,
            "stderr": proc.stderr[-2000:],
        }
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "timeout"}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": str(e)[:500]}

    # Fallback for fresh VPS installs where systemctl --user has no DBUS bus
    # ("No medium found"). `openclaw daemon restart` / `gateway restart` fail
    # in that case; spawn the gateway manually so the node keeps working
    # until the user logs out and back in (or reboots).
    if not result["ok"] and args and args[-1] == "restart":
        stderr = result.get("stderr", "")
        if "No medium found" in stderr or "Failed to connect to bus" in stderr:
            fallback = _spawn_openclaw_gateway(bin_path)
            result["fallback"] = fallback
            if fallback.get("ok"):
                result["ok"] = True
    return result


def _spawn_openclaw_gateway(bin_path: str) -> dict:
    """Kill any running openclaw gateway and relaunch it in the background.
    Used when systemctl --user is unavailable (fresh VPS, no linger session)."""
    subprocess.run(["pkill", "-f", "openclaw gateway"], check=False)
    try:
        subprocess.Popen(
            [bin_path, "gateway"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            stdin=subprocess.DEVNULL,
            start_new_session=True,
            env=_cli_env(),
        )
        return {"ok": True, "method": "spawn"}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": f"spawn_failed: {e}"}


def _gateway_main_pid() -> int | None:
    """Return the gateway process PID, or None if not running.

    Linux: systemctl --user show openclaw-gateway --property=MainPID --value.
    Mac: pgrep -f openclaw-gateway (no systemd, launchd doesn't expose PID
    portably from a non-root context).
    """
    if sys.platform == "darwin":
        try:
            out = subprocess.check_output(
                ["pgrep", "-f", "openclaw-gateway"], text=True, timeout=5,
            ).strip()
            return int(out.splitlines()[0]) if out else None
        except (subprocess.CalledProcessError, ValueError, subprocess.TimeoutExpired):
            return None
    # Linux user service
    env = os.environ.copy()
    env.setdefault("XDG_RUNTIME_DIR", f"/run/user/{os.getuid()}")
    try:
        out = subprocess.check_output(
            ["systemctl", "--user", "show", "openclaw-gateway",
             "--property=MainPID", "--value"],
            text=True, timeout=5, env=env,
        ).strip()
        return int(out) if out and out != "0" else None
    except (subprocess.CalledProcessError, ValueError, subprocess.TimeoutExpired,
            FileNotFoundError):
        return None


def _restart_openclaw_with_verify(timeout: int = 60) -> dict:
    """Restart openclaw and verify the MainPID actually rotated.

    Some hosts return ok=True from `openclaw daemon restart` while the
    gateway process keeps running with the old PID — openclaw.json on disk
    is fresh but the in-memory config stays stale, so the user keeps seeing
    "No API key found for provider X". When that happens, force-kill the old
    PID; systemd Restart=always (Linux) or launchd KeepAlive (Mac) respawns
    it within ~3s.
    """
    old_pid = _gateway_main_pid()
    result = _run_openclaw("daemon", "restart", timeout=timeout)
    result["oldPid"] = old_pid
    if not result.get("ok"):
        result["pidVerified"] = "skipped_restart_failed"
        return result
    time.sleep(3)
    new_pid = _gateway_main_pid()
    result["newPid"] = new_pid
    if old_pid is None:
        result["pidVerified"] = "old_pid_unknown"
        return result
    if new_pid is not None and new_pid != old_pid:
        result["pidVerified"] = "ok"
        return result
    _log(
        f"openclaw restart didn't rotate PID (old={old_pid} new={new_pid}); "
        f"sending SIGTERM to old PID and trusting Restart=always to respawn"
    )
    try:
        os.kill(old_pid, signal.SIGTERM)
    except ProcessLookupError:
        result["pidVerified"] = "old_pid_already_gone"
        return result
    except OSError as e:
        result["pidVerified"] = f"sigterm_failed: {e}"
        return result
    time.sleep(3)
    result["newPid"] = _gateway_main_pid()
    result["pidVerified"] = "forced"
    return result


# ── openclaw.json writer ───────────────────────────────────────

# ── tbrain-models (renombre 2026-10) ──────────────────────────
# Provider del cerebro de texto en openclaw.json: `tbrain-models/<vendor>/<id>`.
MODELS_PROVIDER = "tbrain-models"
# Plugin interno de OpenClaw para imagen/música/video. ÚNICA excepción del
# renombre: OpenClaw solo habla esas APIs a través de su plugin con este id.
# Apunta a la misma URL/key/header que MODELS_PROVIDER. Plan C = plugin propio.
MEDIA_PROVIDER = "openrouter"
MODELS_GATEWAY_AUTH_SECRET = "TBRAIN_MODELS_GATEWAY_AUTH"
MODEL_KEY_V2_CAP = "model-key-v2"
GATEWAY_AUTH_HEADER = "cf-aig-authorization"
# @deprecated transición — nombres previos que aún leen la app 1.14.x
# (`llmMode`) y que mandan el app/CF viejos (comando). Borrar en limpieza.
_LEGACY_TEXT_PROVIDER = "openrouter"
_LEGACY_LLM_MODE = "openrouter"
_LEGACY_APPLY_MODEL_KEY_CMD = "apply_openrouter_key"
# Claves de openclaw.json cuyo valor es un slug de MEDIOS: la migración de
# slugs de texto no entra en ellas.
_MEDIA_SLOT_KEYS = frozenset({
    "mediaModels", "imageGenerationModel", "musicGenerationModel",
    "videoGenerationModel",
})

_CTX_DEFAULTS = {
    MODELS_PROVIDER: 200000,
    MEDIA_PROVIDER: 200000,
    "groq": 131072,
    "ollama": 32768,
    "lmstudio": 131072,
    "llama-cpp": 131072,
}


def _default_context_for(provider: str) -> int:
    return _CTX_DEFAULTS.get(provider, 8192)


_KNOWN_PROVIDER_PREFIXES = frozenset(_CTX_DEFAULTS.keys())


def _split_provider_slug(slug: str) -> tuple[str, str]:
    """`'tbrain-models/qwen/qwen3.6-plus'` → `('tbrain-models', 'qwen/qwen3.6-plus')`.
    Returns `('', slug)` if the slug doesn't start with a known provider
    prefix — keeps interop between the prefixed `agent.model.primary` form
    and the unprefixed `providers[p].models[].id` form."""
    if not isinstance(slug, str) or "/" not in slug:
        return "", slug if isinstance(slug, str) else ""
    head, rest = slug.split("/", 1)
    if head in _KNOWN_PROVIDER_PREFIXES:
        return head, rest
    return "", slug


def _ensure_model_registered(cfg: dict, model_slug: str) -> bool:
    """Idempotently make `model_slug` reachable from a freshly-loaded gateway:
    upsert under `models.providers[p].models[]` (catalog id without the
    provider prefix) and add the same id to `agents.defaults.models`.
    Skips the catalog write if the inferred provider isn't yet configured
    (e.g. a sub-agent install on a node before `apply_model_key`).
    Returns `True` if cfg was modified."""
    model_slug = _canon_text_slug(model_slug)
    provider, catalog_id = _split_provider_slug(model_slug)
    if not provider:
        return False

    changed = False
    providers = (cfg.setdefault("models", {}).setdefault("providers", {}))
    p = providers.get(provider)
    if isinstance(p, dict):
        models_list = p.setdefault("models", [])
        if isinstance(models_list, list) and not any(
            isinstance(m, dict) and m.get("id") == catalog_id for m in models_list
        ):
            entry = {
                "id": catalog_id,
                "name": catalog_id,
                "contextWindow": _default_context_for(provider),
                "maxTokens": 4096,
            }
            if provider == MODELS_PROVIDER:
                # Provider custom: sin esto OpenClaw no pide `usage`.
                entry["compat"] = {"supportsUsageInStreaming": True}
            models_list.append(entry)
            changed = True

    defaults_models = (
        cfg.setdefault("agents", {})
        .setdefault("defaults", {})
        .setdefault("models", {})
    )
    if isinstance(defaults_models, dict) and catalog_id not in defaults_models:
        defaults_models[catalog_id] = {}
        changed = True

    return changed


def _ensure_heartbeat_default() -> None:
    """OpenClaw trae heartbeat con DEFAULT 30m aunque el config no tenga la
    key — cada poll re-manda TODO el contexto de la sesión al LLM y en nodos
    con el hub de modelos de paga es un leak de saldo silencioso (2026-07-13: el
    Oracle Front de Félix quemó su saldo COMPLETO en 2 semanas de polls; el
    heartbeat en TNode no aporta — chat-sync + tnode-wake ya cubren entrega).
    Se persiste APAGADO (`agents.defaults.heartbeat.every: "0m"`). Solo si la
    key está AUSENTE: un valor explícito (dueño o feature futura de
    proactividad) se respeta. Requiere restart del gateway para aplicar, que
    en un nodo fresco ocurre naturalmente en el arranque."""
    try:
        cfg = json.loads(OPENCLAW_JSON_PATH.read_text())
        hb = (
            cfg.setdefault("agents", {})
            .setdefault("defaults", {})
            .setdefault("heartbeat", {})
        )
        if "every" in hb:
            return
        hb["every"] = "0m"
        _write_openclaw_json(cfg)
        _log("heartbeat: default 0m persistido (agents.defaults.heartbeat.every)")
    except Exception as e:  # noqa: BLE001
        _log(f"heartbeat default: {e}")


def _ensure_gateway_policy_floor() -> None:
    """2.11.0 (c): claves de política que un upgrade de OpenClaw puede
    invertir por default. Se escriben explícitas para que el comportamiento
    no dependa del pin. Ambas existen en el schema desde 9.4."""
    try:
        cfg = json.loads(OPENCLAW_JSON_PATH.read_text())
        changed = []
        cc = (
            cfg.setdefault("tools", {})
            .setdefault("message", {})
            .setdefault("crossContext", {})
        )
        if cc.get("allowAcrossProviders") is not False:
            cc["allowAcrossProviders"] = False
            changed.append("tools.message.crossContext.allowAcrossProviders")
        upd = cfg.setdefault("update", {})
        if upd.get("checkOnStart") is not False:
            upd["checkOnStart"] = False
            changed.append("update.checkOnStart")
        if changed:
            _write_openclaw_json(cfg)
            _log("policy floor: %s = false" % ", ".join(changed))
    except Exception as e:  # noqa: BLE001
        _log(f"policy floor: {e}")


def _write_openclaw_json(cfg: dict) -> None:
    """Atomically write openclaw.json with the given config dict."""
    tmp = OPENCLAW_JSON_PATH.with_suffix(".json.tmp")
    tmp.parent.mkdir(parents=True, exist_ok=True)
    with open(tmp, "w") as f:
        json.dump(cfg, f, indent=2)
    os.replace(tmp, OPENCLAW_JSON_PATH)


def _strip_provider_prefix(slug: str, provider: str) -> str:
    """Get the INTERNAL provider id (no prefix) — what providers[p].models[].id
    must be. Idempotent: strips `<provider>/` if present, else no-op.
    """
    if not isinstance(slug, str) or not isinstance(provider, str):
        return slug
    needle = provider + "/"
    if slug.startswith(needle):
        return slug[len(needle):]
    return slug


def _build_prefixed_slug(provider: str, model: str) -> str:
    """Get the PREFIXED slug — what agents.defaults.models[key] and
    agents.list[].model.primary must be. OpenClaw 2026.5.x exige que el
    slug del agente lleve el prefix del provider local (ver memoria
    `or_api_quirks` §6); sin prefix, OpenClaw interpreta `<vendor>/<id>`
    como `<provider-local>/<model-id>` y falla con `No API key for
    provider <vendor>`. Idempotente: si ya está prefixed, no-op.
    """
    if not isinstance(model, str) or not isinstance(provider, str):
        return model
    needle = provider + "/"
    if model.startswith(needle):
        return model
    return needle + model


def _canon_text_slug(slug):
    """Slug de un modelo de TEXTO en su forma vigente: el prefix del provider
    previo (`openrouter/…`, que aún mandan tarjetas de sub-agentes y clientes
    viejos) pasa a `tbrain-models/…`. Idempotente; cualquier otro slug
    (local, custom, ya canónico) se devuelve igual. NO usar con slugs de
    medios — esos viven en MEDIA_PROVIDER."""
    if isinstance(slug, str) and slug.startswith(_LEGACY_TEXT_PROVIDER + "/"):
        return MODELS_PROVIDER + "/" + slug[len(_LEGACY_TEXT_PROVIDER) + 1:]
    return slug


def _media_model_ids(cfg: dict) -> set:
    """Ids internos (`<vendor>/<id>`) de los modelos de medios: los que el
    nodo tiene en sus ranuras + los defaults sembrados por la plataforma."""
    ids = set()
    prefix = MEDIA_PROVIDER + "/"

    def walk(v):
        if isinstance(v, str) and v.startswith(prefix):
            ids.add(v[len(prefix):])
        elif isinstance(v, dict):
            for x in v.values():
                walk(x)
        elif isinstance(v, list):
            for x in v:
                walk(x)

    defaults = (cfg.get("agents") or {}).get("defaults") or {}
    if isinstance(defaults, dict):
        for k in _MEDIA_SLOT_KEYS:
            walk(defaults.get(k))
    for slug in _DEFAULT_MEDIA_MODELS.values():
        walk(slug)
    return ids


def _migrate_models_schema(cfg: dict) -> bool:
    """Migración in-place del esquema previo al renombre (2.12.0):
    - entradas de TEXTO de `models.providers.<previo>.models[]` se mueven a
      `models.providers.tbrain-models.models[]` (las de medios se quedan);
    - todo slug `<previo>/<vendor>/<id>` de texto en el resto del archivo
      (defaults.models, defaults.model.primary/fallbacks, agents.list[].model,
      …) pasa a `tbrain-models/…`. Las ranuras de medios no se tocan.
    Idempotente. No escribe el archivo; devuelve True si cambió `cfg`."""
    changed = False
    media_ids = _media_model_ids(cfg)
    providers = (cfg.get("models") or {}).get("providers")
    if isinstance(providers, dict):
        legacy = providers.get(_LEGACY_TEXT_PROVIDER)
        if isinstance(legacy, dict) and isinstance(legacy.get("models"), list):
            keep, move = [], []
            for m in legacy["models"]:
                mid = m.get("id") if isinstance(m, dict) else None
                (keep if (not mid or mid in media_ids) else move).append(m)
            if move:
                text = providers.setdefault(MODELS_PROVIDER, {})
                tlist = text.setdefault("models", [])
                have = {x.get("id") for x in tlist if isinstance(x, dict)}
                for m in move:
                    if m.get("id") not in have:
                        tlist.append(m)
                legacy["models"] = keep
                changed = True

    def conv(v):
        if isinstance(v, str) and v.startswith(_LEGACY_TEXT_PROVIDER + "/"):
            rest = v[len(_LEGACY_TEXT_PROVIDER) + 1:]
            if rest not in media_ids:
                return MODELS_PROVIDER + "/" + rest
        return v

    def walk(node):
        nonlocal changed
        if isinstance(node, dict):
            for k in list(node.keys()):
                if k in _MEDIA_SLOT_KEYS:
                    continue
                v = node[k]
                nk = conv(k)
                if isinstance(v, (dict, list)):
                    walk(v)
                else:
                    nv = conv(v)
                    if nv != v:
                        node[k] = nv
                        changed = True
                if nk != k:
                    if nk in node and isinstance(node[nk], dict) and isinstance(v, dict):
                        node[nk] = {**v, **node[nk]}
                    else:
                        node[nk] = node[k]
                    del node[k]
                    changed = True
        elif isinstance(node, list):
            for i, v in enumerate(node):
                if isinstance(v, (dict, list)):
                    walk(v)
                else:
                    nv = conv(v)
                    if nv != v:
                        node[i] = nv
                        changed = True

    for top, sub in cfg.items():
        if top == "models":
            continue  # providers ya se migraron arriba
        if isinstance(sub, (dict, list)):
            walk(sub)
    return changed


def _needs_models_migration(cfg: dict) -> bool:
    """¿Este openclaw.json todavía tiene el esquema previo al renombre?"""
    if not isinstance(cfg, dict):
        return False
    providers = (cfg.get("models") or {}).get("providers") or {}
    legacy = providers.get(_LEGACY_TEXT_PROVIDER)
    if not isinstance(legacy, dict) or not _apikey_present(legacy.get("apiKey")):
        return False
    if MODELS_PROVIDER not in providers:
        return True
    probe = json.loads(json.dumps(cfg))
    return _migrate_models_schema(probe)


# v1.11.0 — default media-generation models seeded on first model-hub
# provision so a fresh node can generate image/music/video out of the box,
# mirroring how the cerebro (chat) model is applied. Economic tier; the user
# can switch any of them in Mente (agent.{image,music,video}Model.set), which
# wins because we only `setdefault` (never overwrite an explicit choice).
_DEFAULT_MEDIA_MODELS = {
    "imageGenerationModel": MEDIA_PROVIDER + "/google/gemini-3.1-flash-image-preview",
    "musicGenerationModel": MEDIA_PROVIDER + "/google/lyria-3-clip-preview",
    "videoGenerationModel": MEDIA_PROVIDER + "/x-ai/grok-imagine-video",
}


def _apply_provider_to_openclaw(
    provider: str,
    base_url: str,
    model: str,
    api_key: str = "",
    ctx: int | None = None,
    max_tokens: int = 4096,
    api_key_secret_name: str | None = None,
) -> dict:
    """Upsert a provider block inside openclaw.json. Returns updated cfg.

    Merge semantics (v1.3.0+): `providers[p].models[]` and
    `agents.defaults.models` are extended in-place rather than replaced.
    Earlier versions clobbered the expanded model catalog (e.g. Cerebro's
    14-model list and any sub-agent's recommended model) every time the
    user re-applied a model-hub key, leaving the gateway with a single
    allowed model and breaking sub-agent delegation.

    v1.5.0+ — slug normalization (fix OpenClaw 2026.5.x `Unknown model`):
    `providers[p].models[].id` recibe el slug INTERNO sin prefix
    (`qwen/qwen3.6-plus`), mientras que `agents.defaults.models[key]`
    recibe el slug PREFIXED (`tbrain-models/qwen/qwen3.6-plus`). El parser
    de OpenClaw splittea por la primera `/` para extraer el provider
    local; sin prefix del provider, falla con `No API key found for
    provider <vendor>`. Ver memoria `or_api_quirks` §6 para el contrato.

    Idempotente — acepta `model` con o sin prefix; internal_id / prefixed
    se derivan via helpers `_strip_provider_prefix` / `_build_prefixed_slug`.

    El legacy `agents.defaults.model.primary` (singular) se borra en cada
    escritura — desde OpenClaw v2026.4.24+ produce `Unknown model`.
    """
    internal_id = _strip_provider_prefix(model, provider)
    prefixed_slug = _build_prefixed_slug(provider, internal_id)

    # Train 2.0: key al shared store + SecretRef en el config (ver bloque
    # Credential Management arriba). Si el store set falla, fallback a
    # plaintext — un nodo con LLM y residuo auditable gana a un nodo mudo.
    # F3a: si el caller trae `api_key_secret_name`, el app YA depositó el
    # valor en el store vía RPC `secrets.store.set` (la key jamás pasó por
    # Firestore) — aquí solo se escribe el SecretRef.
    key_value: object = api_key or ""
    used_ref = False
    if api_key_secret_name and _openclaw_is_v2() \
            and re.match(r"^[A-Z][A-Z0-9_]{0,127}$", api_key_secret_name):
        key_value = _secret_ref(api_key_secret_name)
        used_ref = True
    elif api_key and _openclaw_is_v2():
        _sname = _secret_store_name(provider)
        if _store_secret(_sname, api_key):
            key_value = _secret_ref(_sname)
            used_ref = True

    cfg = read_openclaw_json() or {}
    providers = cfg.setdefault("models", {}).setdefault("providers", {})
    p = providers.setdefault(provider, {
        "baseUrl": base_url,
        "apiKey": key_value,
        "models": [],
    })
    p["baseUrl"] = base_url
    if api_key or used_ref:
        p["apiKey"] = key_value

    models_list = p.setdefault("models", [])
    if not isinstance(models_list, list):
        models_list = []
        p["models"] = models_list
    existing = next(
        (m for m in models_list if isinstance(m, dict) and m.get("id") == internal_id),
        None,
    )
    if existing is None:
        models_list.append({
            "id": internal_id,
            "name": internal_id,
            "contextWindow": ctx or _default_context_for(provider),
            "maxTokens": max_tokens,
        })
    else:
        if ctx:
            existing["contextWindow"] = ctx
        if max_tokens:
            existing["maxTokens"] = max_tokens

    agents_defaults = cfg.setdefault("agents", {}).setdefault("defaults", {})
    agents_defaults.setdefault("models", {}).setdefault(prefixed_slug, {})
    agents_defaults.pop("model", None)  # drop legacy singular key

    # Seed default media-generation models so a freshly-provisioned node can
    # generate image/music/video without the user hand-picking them in Mente.
    # Media-provider only (the defaults are media slugs that need the node's key)
    # and setdefault-only (a prior Mente choice or sub-agent card is kept).
    if provider == MEDIA_PROVIDER:
        if _openclaw_is_v2():
            _mm = agents_defaults.setdefault("mediaModels", {})
            _v2_slot = {"imageGenerationModel": "image",
                        "musicGenerationModel": "music",
                        "videoGenerationModel": "video"}
            if isinstance(_mm, dict):
                for _slot, _default_slug in _DEFAULT_MEDIA_MODELS.items():
                    _mm.setdefault(_v2_slot[_slot], _default_slug)
                    agents_defaults.pop(_slot, None)
        else:
            for _slot, _default_slug in _DEFAULT_MEDIA_MODELS.items():
                agents_defaults.setdefault(_slot, _default_slug)

    _write_openclaw_json(cfg)
    # Rotación con ref SIN cambio de config (mismo NAME, valor nuevo en el
    # store): el file-watcher no tiene nada que recargar — el reload de
    # secrets es quien publica el valor nuevo al snapshot del gateway.
    if used_ref:
        _secrets_reload()
    return cfg


def _apply_models_providers(
    base_url: str,
    model: str,
    api_key: str,
    gateway_auth: str | None = None,
    max_tokens: int = 4096,
    media_base_url: str | None = None,
) -> dict:
    """Escribe el cerebro de texto `tbrain-models` y el provider de medios
    (MEDIA_PROVIDER) con la MISMA url, key y header del AI Gateway, migrando
    antes el esquema previo. Devuelve el cfg escrito.

    - key → store `TBRAIN_MODELS_API_KEY` (SecretRef en 2.x; plaintext si el
      store falla — un nodo con LLM gana a un nodo mudo).
    - `gateway_auth` ("Bearer …") → store `TBRAIN_MODELS_GATEWAY_AUTH` y
      header `cf-aig-authorization`; None = sin gateway → se QUITA el header
      (el interruptor central apagado regresa el nodo a la URL directa).
    - `agents.defaults.model.primary` = `tbrain-models/<model>` salvo que el
      dueño ya tenga un primary de texto distinto (Mente gana).
    - modelos de texto con `compat.supportsUsageInStreaming` (provider custom:
      sin esto OpenClaw no pide `usage` y CTX/consumo quedan en blanco)."""
    v2 = _openclaw_is_v2()
    used_ref = False
    key_value: object = api_key
    key_name = _secret_store_name(MODELS_PROVIDER)
    if v2 and _store_secret(key_name, api_key):
        key_value = _secret_ref(key_name)
        used_ref = True
    header_value: object | None = None
    if gateway_auth:
        header_value = gateway_auth
        if v2 and _store_secret(MODELS_GATEWAY_AUTH_SECRET, gateway_auth):
            header_value = _secret_ref(MODELS_GATEWAY_AUTH_SECRET)
            used_ref = True

    cfg = read_openclaw_json() or {}
    _migrate_models_schema(cfg)
    providers = cfg.setdefault("models", {}).setdefault("providers", {})
    for name in (MODELS_PROVIDER, MEDIA_PROVIDER):
        prov = providers.get(name)
        if not isinstance(prov, dict):
            prov = providers[name] = {}
        prov["baseUrl"] = (
            media_base_url if name == MEDIA_PROVIDER and media_base_url else base_url
        )
        prov["apiKey"] = key_value
        prov.setdefault("models", [])
        headers = prov.get("headers") if isinstance(prov.get("headers"), dict) else {}
        if header_value is not None:
            headers[GATEWAY_AUTH_HEADER] = header_value
        else:
            headers.pop(GATEWAY_AUTH_HEADER, None)
        if headers:
            prov["headers"] = headers
        else:
            prov.pop("headers", None)

    # El plugin de medios NO lee `headers` en sus peticiones de imagen/
    # música/video: arma las suyas desde `request.headers` (OpenClaw 9.4,
    # extensions/openrouter/generation-request-context). Sin esto el gateway
    # responde 401 a medios aunque el texto funcione.
    media = providers[MEDIA_PROVIDER]
    req = media.get("request") if isinstance(media.get("request"), dict) else {}
    rh = req.get("headers") if isinstance(req.get("headers"), dict) else {}
    if header_value is not None:
        rh[GATEWAY_AUTH_HEADER] = header_value
    else:
        rh.pop(GATEWAY_AUTH_HEADER, None)
    if rh:
        req["headers"] = rh
    else:
        req.pop("headers", None)
    if req:
        media["request"] = req
    else:
        media.pop("request", None)

    text = providers[MODELS_PROVIDER]
    text["api"] = "openai-completions"
    internal_id = _strip_provider_prefix(
        _strip_provider_prefix(model, _LEGACY_TEXT_PROVIDER), MODELS_PROVIDER
    )
    tlist = text["models"]
    if not any(isinstance(m, dict) and m.get("id") == internal_id for m in tlist):
        tlist.append({
            "id": internal_id,
            "name": internal_id,
            "contextWindow": _default_context_for(MODELS_PROVIDER),
            "maxTokens": max_tokens,
        })
    for m in tlist:
        if isinstance(m, dict):
            m.setdefault("name", m.get("id"))
            compat = m.get("compat") if isinstance(m.get("compat"), dict) else {}
            compat["supportsUsageInStreaming"] = True
            m["compat"] = compat

    prefixed = _build_prefixed_slug(MODELS_PROVIDER, internal_id)
    defaults = cfg.setdefault("agents", {}).setdefault("defaults", {})
    defaults.setdefault("models", {}).setdefault(prefixed, {})
    cur = defaults.get("model") if isinstance(defaults.get("model"), dict) else {}
    if not cur.get("primary"):
        # Solo si no hay ninguno: un primary local (LM Studio) o elegido en
        # Mente se respeta; los de texto del esquema previo ya los migró
        # _migrate_models_schema.
        cur["primary"] = prefixed
        defaults["model"] = cur

    # Medios por defecto (setdefault: una elección previa en Mente se respeta).
    if v2:
        _mm = defaults.setdefault("mediaModels", {})
        _v2_slot = {"imageGenerationModel": "image",
                    "musicGenerationModel": "music",
                    "videoGenerationModel": "video"}
        if isinstance(_mm, dict):
            for _slot, _slug in _DEFAULT_MEDIA_MODELS.items():
                _mm.setdefault(_v2_slot[_slot], _slug)
                defaults.pop(_slot, None)
    else:
        for _slot, _slug in _DEFAULT_MEDIA_MODELS.items():
            defaults.setdefault(_slot, _slug)

    _write_openclaw_json(cfg)
    if used_ref:
        _secrets_reload()
    return cfg


# ── Command handlers ───────────────────────────────────────────

def handle_update_llm_provider(token: dict, params: dict) -> dict:
    provider = str(params.get("provider") or "").strip()
    base_url = str(params.get("baseUrl") or "").strip()
    model = str(params.get("model") or "").strip()
    api_key = str(params.get("apiKey") or "")
    # F3a: el sheet del app manda solo el NOMBRE de la entrada del store
    # (la key viajó por WS directo al gateway, nunca por este comando).
    api_key_secret_name = str(params.get("apiKeySecretName") or "").strip() or None
    ctx = params.get("ctx")
    max_tokens = params.get("maxTokens") or 4096

    if provider not in _CTX_DEFAULTS and provider != "openai-compat":
        return {
            "status": "error",
            "result": {"error": f"unsupported_provider: {provider}"},
        }
    if not base_url or not model:
        return {
            "status": "error",
            "result": {"error": "missing_baseUrl_or_model"},
        }

    try:
        _apply_provider_to_openclaw(
            provider, base_url, model, api_key,
            ctx=int(ctx) if ctx else None,
            max_tokens=int(max_tokens),
            api_key_secret_name=api_key_secret_name,
        )
    except Exception as e:  # noqa: BLE001
        return {"status": "error", "result": {"error": f"write_failed: {e}"}}

    # El gateway hot-recarga models.providers (apiKey incl.) + agents.defaults.models
    # de openclaw.json — verificado en vivo en 2026.6.10 (PID estable, log
    # `config hot reload applied`). NO reiniciamos: el restart sobraba y causaba
    # el parpadeo "gateway starting; retry shortly".
    # Push the new state up immediately so the client sees it.
    try:
        new_state = push_openclaw_config(token)
    except Exception as e:  # noqa: BLE001
        _log(f"post-update state push failed: {e}")
        new_state = None

    return {
        "status": "done",
        "result": {
            "provider": provider,
            "applied": "hot-reload",
            "llmMode": (new_state or {}).get("llmMode"),
        },
    }


def handle_set_agent_params(token: dict, params: dict) -> dict:
    """Fija los parámetros de generación por-agente (temperature, maxTokens)
    en `agents.list[<agentId>].params` — la ubicación ESTÁNDAR de OpenClaw que
    el runtime de texto lee (`params.temperature` / `params.maxTokens`, ver
    docs.openclaw.ai/help/faq). El campo `extraParams` NO es válido (el config
    validator lo rechaza con `Unrecognized key`).

    Verificado en vivo (2026-06-26): el gateway recoge los cambios de
    `agents.list[].params` en el siguiente turno SIN reiniciar, así que solo
    reescribimos openclaw.json. `temperature` se clampa a [0,2]; `maxTokens`
    debe ser entero positivo. Pasar `null` en cualquiera lo BORRA (vuelve al
    default del proveedor). agentId default = "main" (el agente del dueño).
    """
    agent_id = str(params.get("agentId") or "main").strip()
    has_temp = "temperature" in params
    has_max = "maxTokens" in params
    temp = params.get("temperature")
    max_tokens = params.get("maxTokens")

    if has_temp and temp is not None:
        try:
            temp = max(0.0, min(2.0, float(temp)))
        except (TypeError, ValueError):
            return {"status": "error", "result": {"error": "invalid_temperature"}}
    if has_max and max_tokens is not None:
        try:
            max_tokens = int(max_tokens)
        except (TypeError, ValueError):
            return {"status": "error", "result": {"error": "invalid_maxTokens"}}
        if max_tokens <= 0:
            max_tokens = None

    cfg = read_openclaw_json() or {}
    _agents_section = cfg.setdefault("agents", {})
    agents_list = _roster_load(_agents_section)
    entry = next(
        (a for a in agents_list if isinstance(a, dict) and a.get("id") == agent_id),
        None,
    )
    if entry is None:
        return {"status": "error", "result": {"error": f"agent_not_found: {agent_id}"}}

    p = entry.get("params")
    if not isinstance(p, dict):
        p = {}
    if has_temp:
        if temp is None:
            p.pop("temperature", None)
        else:
            p["temperature"] = temp
    if has_max:
        if max_tokens is None:
            p.pop("maxTokens", None)
        else:
            p["maxTokens"] = max_tokens
    if p:
        entry["params"] = p
    else:
        entry.pop("params", None)

    _roster_store(_agents_section, agents_list)
    _write_openclaw_json(cfg)
    _log(
        f"set_agent_params {agent_id}: "
        f"temperature={p.get('temperature')} maxTokens={p.get('maxTokens')}"
    )

    try:
        push_openclaw_config(token)
    except Exception as e:  # noqa: BLE001
        _log(f"post set_agent_params push failed: {e}")

    return {"status": "done", "result": {"agentId": agent_id, "params": p}}


def handle_restart_openclaw(token: dict, params: dict) -> dict:
    result = _restart_openclaw_with_verify()
    return {
        "status": "done" if result.get("ok") else "error",
        "result": result,
    }


def handle_detect_local_models(token: dict, params: dict) -> dict:
    base_url = str(params.get("baseUrl") or "").strip().rstrip("/")
    provider = str(params.get("provider") or "").strip()
    if not base_url:
        return {"status": "error", "result": {"error": "missing_baseUrl"}}

    try:
        if provider == "ollama":
            data = _http_get(f"{base_url}/api/tags")
            models = [m.get("name") for m in data.get("models", []) if m.get("name")]
        else:
            # OpenAI-compatible (lmstudio, llama-cpp, openai-compat)
            data = _http_get(f"{base_url}/v1/models")
            models = [m.get("id") for m in data.get("data", []) if m.get("id")]
    except urllib.error.URLError as e:
        return {"status": "error", "result": {"error": f"unreachable: {e.reason}"}}
    except Exception as e:  # noqa: BLE001
        return {"status": "error", "result": {"error": str(e)[:500]}}

    return {
        "status": "done",
        "result": {"provider": provider, "baseUrl": base_url, "models": models},
    }


def _restart_gateway_blocking(timeout_s: float = 45.0) -> bool:
    """Reinicia el gateway y espera a que el puerto 18789 vuelva a aceptar
    conexiones. Camino: systemctl --user (unit openclaw-gateway) → fallback
    CLI `openclaw gateway restart` (que a su vez trae el fallback de spawn
    manual para VPS sin bus). Usado en la PRIMERA activación de key, donde
    el hot-reload por file-watcher demostró no ser confiable.

    1.83.0 (gotcha E2E 2026-08-28): si systemctl Y el fallback CLI fallan,
    el check de puerto veía el gateway VIEJO aún arriba y confirmaba en
    FALSO (config nueva jamás cargada). Ahora: MainPID antes/después en el
    camino systemctl, y el rc del fallback se respeta — ambos caminos
    fallidos = False sin tocar el puerto."""

    def _main_pid() -> str:
        q = subprocess.run(
            ["systemctl", "--user", "show", "openclaw-gateway", "-p", "MainPID"],
            capture_output=True, text=True, check=False, env=_cli_env(),
        )
        return (q.stdout or "").strip() if q.returncode == 0 else ""

    pid_before = _main_pid()
    r = subprocess.run(
        ["systemctl", "--user", "restart", "openclaw-gateway"],
        capture_output=True, text=True, check=False, env=_cli_env(),
    )
    restarted = r.returncode == 0
    if restarted and pid_before and pid_before not in ("MainPID=0", ""):
        # systemctl "exitoso" con el MISMO pid = no reinició (bus roto).
        if _main_pid() == pid_before:
            _log("gateway restart: systemctl rc=0 pero MainPID no cambió — CLI fallback")
            restarted = False
    if not restarted:
        if r.returncode != 0:
            _log(
                "gateway restart via systemctl failed "
                f"({(r.stderr or '').strip()[:120]}); CLI fallback"
            )
        fb = _run_openclaw("gateway", "restart", timeout=60)
        if fb.get("ok") is not True:
            _log(
                "gateway restart: CLI fallback también falló "
                f"({str(fb)[:120]}) — NO confirmo (config vieja en memoria)"
            )
            return False
    deadline = time.time() + timeout_s
    while time.time() < deadline:
        try:
            with socket.create_connection(("127.0.0.1", 18789), timeout=2):
                # Colchón corto: el puerto abre antes de que el pre-warm de
                # providers termine (~10s medidos); dale aire al runtime.
                time.sleep(8)
                return True
        except OSError:
            time.sleep(2)
    _log("gateway restart: port 18789 not up within timeout")
    return False


def handle_apply_model_key(token: dict, params: dict) -> dict:
    """Fetch the node's tbrain-models key via pullLLMConfig (HMAC) and apply
    it to openclaw.json (text provider + media provider, AI Gateway if the
    central switch enables this node). The key must already have been minted
    by the Flutter app calling the `mintNodeKey` callable. Also registered
    under the legacy command name (transición)."""
    cfg = load_config()

    # ¿Primera activación? Leído ANTES de escribir: si openclaw.json aún no
    # tiene key de modelos, no hay sesiones vivas que preservar y el done
    # se garantiza con un restart del gateway (ver changelog 1.54.0).
    first_activation = True
    try:
        _prev_cfg = json.loads((OPENCLAW_DIR / "openclaw.json").read_text())
        _prev_provs = (_prev_cfg.get("models") or {}).get("providers") or {}
        first_activation = not any(
            _apikey_present((_prev_provs.get(n) or {}).get("apiKey"))
            for n in (MODELS_PROVIDER, _LEGACY_TEXT_PROVIDER)
        )
    except Exception:  # noqa: BLE001 — sin archivo = primera activación
        first_activation = True
    pull_url = cfg.get("pullLLMConfigUrl") or (
        f"https://us-central1-{PROJECT_ID}.cloudfunctions.net/pullLLMConfig"
    )

    # Pull the minted key — retry transient failures (read timeouts /
    # connection blips). A single read-timeout used to drop the command to
    # status=error with no retry, leaving the node without its LLM until a
    # manual re-trigger. HTTP errors (auth/logic) stay terminal. Re-sign per
    # attempt so a retry never trips replay / stale-timestamp checks.
    resp = None
    last_err: Exception | None = None
    for attempt in range(4):
        ts = str(int(time.time() * 1000))
        nonce = py_secrets.token_hex(16)
        signing = f'{cfg["nodeId"]}:{ts}:{nonce}'  # legacy signature (no scope)
        mac = hmac.new(
            cfg["nodeSecret"].encode("utf-8"),
            signing.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        try:
            resp = _http_request(
                "POST",
                pull_url,
                {
                    "nodeId": cfg["nodeId"],
                    "timestamp": ts,
                    "nonce": nonce,
                    "signature": mac,
                    "capabilities": [MODEL_KEY_V2_CAP],
                },
            )
            break
        except urllib.error.HTTPError as e:
            try:
                err_body = json.loads(e.read().decode("utf-8"))
            except Exception:
                err_body = {"error": e.reason}
            return {
                "status": "error",
                "result": {"error": f"pull_failed_{e.code}", "detail": err_body},
            }
        except (urllib.error.URLError, OSError) as e:  # noqa: BLE001
            last_err = e
            _log(
                f"apply_model_key pull attempt {attempt + 1}/4 "
                f"transient error: {e}"
            )
            if attempt < 3:
                time.sleep(2 * (2 ** attempt))  # 2s, 4s, 8s
    if resp is None:
        return {
            "status": "error",
            "result": {
                "error": f"pull_unreachable_after_retries: {str(last_err)[:200]}"
            },
        }

    api_key = resp.get("apiKey")
    model = resp.get("model") or "qwen/qwen3.6-plus"
    base_url = (resp.get("baseUrl") or "").strip()
    gateway_auth = resp.get("gatewayAuthorization") or None
    # 2.12.1: base propia de medios (proxy que reescribe polling_url).
    media_base_url = (resp.get("mediaBaseUrl") or "").strip() or None
    # Metadata de la key DIRECTO en el hub (el gateway no reenvía GET /key);
    # servidores viejos no lo mandan → mismo base_url de siempre.
    key_probe_url = (resp.get("keyProbeUrl") or "").strip()
    if not api_key:
        return {"status": "error", "result": {"error": "no_api_key_returned"}}
    if not base_url:
        return {"status": "error", "result": {"error": "no_base_url_returned"}}

    # El gateway hot-recarga models.providers (apiKey incl.) + agents.defaults.models
    # de openclaw.json — verificado en vivo en 2026.6.10 (PID estable, log
    # `config hot reload applied (models.providers.<p>.apiKey)`). NO
    # reiniciamos: el restart sobraba y era la causa del parpadeo
    # "gateway starting; retry shortly" al asignar saldo (dropeaba los WS vivos).
    try:
        _apply_models_providers(
            base_url, model, api_key, gateway_auth, media_base_url=media_base_url
        )
    except Exception as e:  # noqa: BLE001
        return {"status": "error", "result": {"error": f"write_failed: {e}"}}
    applied_at = time.time()

    # Una key recién minteada puede tardar MINUTOS en estar viva en el hub
    # (401 "User not found" mientras propaga; medido ~4.5 min, E2E beta
    # 2026-07-12). El cliente retiene el primer mensaje del usuario hasta que
    # este comando complete — así que `done` debe significar "el agente YA
    # puede responder", no solo "la key quedó escrita". Sondeamos el endpoint
    # de metadata de la key (GET {base_url}/key, costo $0 — por el gateway si
    # está encendido, con su header) hasta que el hub la acepte, con tope de 5 min. Si el tope vence, completamos igual (la key
    # está aplicada y vivirá sola) reportando keyLive=false para diagnóstico.
    key_live = False
    probe_url = key_probe_url or (base_url.rstrip("/") + "/key")
    probe_started = time.time()
    probe_deadline = probe_started + 300
    _log("apply_model_key: probing key liveness against the model hub")
    probe_headers = {"Authorization": f"Bearer {api_key}"}
    if gateway_auth and not key_probe_url:
        probe_headers[GATEWAY_AUTH_HEADER] = gateway_auth
    while time.time() < probe_deadline:
        try:
            probe_req = urllib.request.Request(probe_url, headers=probe_headers)
            with urllib.request.urlopen(probe_req, timeout=10) as r:
                if 200 <= r.status < 300:
                    key_live = True
                    break
        except urllib.error.HTTPError as e:
            if e.code not in (401, 403, 404):
                # Respuesta inesperada del endpoint de metadata (5xx, rate
                # limit): no retengas el done por un probe roto — la key
                # puede estar perfectamente viva.
                _log(
                    f"key-liveness probe unexpected HTTP {e.code}; "
                    "assuming live"
                )
                key_live = True
                break
        except (urllib.error.URLError, OSError) as e:  # noqa: BLE001
            _log(f"key-liveness probe transient: {e}")
        time.sleep(12)
    waited_s = int(time.time() - probe_started)
    _log(f"apply_model_key: keyLive={key_live} after {waited_s}s gateway={bool(gateway_auth)}")

    applied_via = "hot-reload"
    if first_activation:
        # PRIMERA activación: el file-watcher del gateway puede morir
        # silencioso (nodo 3e549d66, 2026-07-14: key escrita y viva, cero
        # reloads en el log, primer turno sin provider). Restart determinista:
        # barato (no hay sesiones vivas) y el cliente retiene el primer
        # mensaje hasta este done.
        applied_via = "gateway-restart"
        _log("apply_model_key: first activation — restarting gateway")
        if not _restart_gateway_blocking():
            applied_via = "gateway-restart-timeout"
    else:
        # Re-asignación/top-up: hot-reload (la key vieja sigue válida durante
        # la rotación; un restart dropearía WS vivos). Colchón: el
        # file-watcher tarda ~10s en aplicar el openclaw.json nuevo (medido
        # E2E beta 2026-07-12). Garantiza ≥15s entre el write y el done.
        reload_cushion = 15 - (time.time() - applied_at)
        if reload_cushion > 0:
            _log(
                f"apply_model_key: hot-reload cushion {reload_cushion:.0f}s"
            )
            time.sleep(reload_cushion)

    try:
        new_state = push_openclaw_config(token)
    except Exception as e:  # noqa: BLE001
        _log(f"post-apply state push failed: {e}")
        new_state = None

    return {
        "status": "done",
        "result": {
            "provider": MODELS_PROVIDER,
            "model": model,
            "viaGateway": bool(gateway_auth),
            "applied": applied_via,
            "llmMode": (new_state or {}).get("llmMode"),
            "keyLive": key_live,
            "keyLiveWaitS": waited_s,
        },
    }


# ── Sub-agents handlers ────────────────────────────────────────
# install/uninstall/restart_for_subagents commands let the user toggle
# individual sub-agents from the app on a per-node basis. Each install
# fetches the curated agent files (SOUL.md / AGENTS.md / IDENTITY.md)
# from `agentsCatalog/{agentId}` in Firestore, materializes them into
# `~/.openclaw/agents/<id>/agent/`, and updates `agents.list[]` plus
# `main.subagents.allowAgents`. Uninstall removes the curated files
# (preserving runtime state in `.openclaw/`) and revokes the entry.
#
# Replaces the former `tnode-agents-sync` polling daemon — sub-agents
# are now user-driven, not pre-installed wholesale.

_AGENTS_DIR = OPENCLAW_DIR / "agents"
_SUBAGENT_FILES = ("SOUL.md", "AGENTS.md", "IDENTITY.md")
_SUBAGENT_DEFAULT_MODEL = MODELS_PROVIDER + "/qwen/qwen3.6-plus"
_AGENTS_INDEX_PATH = OPENCLAW_DIR / "agency-agents" / "AGENTS_INDEX.md"
# TEAM_INDEX.md = roster de TNodes-peer a los que delegar (skill tnode-delegate),
# hermano dedicado de AGENTS_INDEX.md. Lo compone la CF (target="team", lee
# peers/ + el toolsJson de cada peer) y el daemon lo renderiza como archivo
# completo por hash (ver "TEAM_INDEX.md renderer"). Sin peers → se borra.
_TEAM_INDEX_PATH = OPENCLAW_DIR / "agency-agents" / "TEAM_INDEX.md"


def _firestore_get_agent_doc(token: dict, agent_id: str) -> dict | None:
    """Read agentsCatalog/{agent_id} via Firestore REST."""
    url = (
        f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
        f"/databases/(default)/documents/agentsCatalog/{agent_id}"
    )
    try:
        req = urllib.request.Request(
            url,
            headers={"Authorization": f'Bearer {token["idToken"]}'},
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise


def _fs_unwrap(value: dict):
    """Convert a Firestore REST typed value into a native Python object."""
    if "stringValue" in value:
        return value["stringValue"]
    if "integerValue" in value:
        return int(value["integerValue"])
    if "doubleValue" in value:
        return float(value["doubleValue"])
    if "booleanValue" in value:
        return value["booleanValue"]
    if "nullValue" in value:
        return None
    if "timestampValue" in value:
        return value["timestampValue"]
    if "mapValue" in value:
        return {
            k: _fs_unwrap(v)
            for k, v in value["mapValue"].get("fields", {}).items()
        }
    if "arrayValue" in value:
        return [_fs_unwrap(v) for v in value["arrayValue"].get("values", [])]
    return None


def _firestore_upsert_installed_subagent(
    token: dict, agent_id: str, payload: dict
) -> None:
    """Write `users/{uid}/nodes/{nodeId}/installedSubagents/{agent_id}`.
    Uses PATCH with documentMask to be idempotent."""
    cfg = load_config()
    uid = token["uid"]
    node_id = cfg["nodeId"]
    fields = {}
    for k, v in payload.items():
        if isinstance(v, str):
            fields[k] = {"stringValue": v}
        elif isinstance(v, bool):
            fields[k] = {"booleanValue": v}
        elif isinstance(v, int):
            fields[k] = {"integerValue": str(v)}
        elif v is None:
            fields[k] = {"nullValue": None}
    mask = "&".join(f"updateMask.fieldPaths={k}" for k in payload.keys())
    url = (
        f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
        f"/databases/(default)/documents/users/{uid}/nodes/{node_id}"
        f"/installedSubagents/{agent_id}?{mask}"
    )
    body = json.dumps({"fields": fields}).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=body,
        headers={
            "Authorization": f'Bearer {token["idToken"]}',
            "Content-Type": "application/json",
        },
        method="PATCH",
    )
    with urllib.request.urlopen(req, timeout=15) as resp:
        resp.read()


def _firestore_delete_installed_subagent(token: dict, agent_id: str) -> None:
    cfg = load_config()
    uid = token["uid"]
    node_id = cfg["nodeId"]
    url = (
        f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
        f"/databases/(default)/documents/users/{uid}/nodes/{node_id}"
        f"/installedSubagents/{agent_id}"
    )
    req = urllib.request.Request(
        url,
        headers={"Authorization": f'Bearer {token["idToken"]}'},
        method="DELETE",
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            resp.read()
    except urllib.error.HTTPError as e:
        if e.code != 404:
            raise


def _firestore_get_mcp_catalog_doc(token: dict, server_id: str) -> dict | None:
